PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE user_points (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, task_id INTEGER REFERENCES tasks(id) ON DELETE SET NULL, progress_entry_id INTEGER REFERENCES progress_entries(id) ON DELETE SET NULL, amount REAL NOT NULL, delta_pct REAL NOT NULL, assignee_count INTEGER NOT NULL, awarded_at TEXT NOT NULL DEFAULT (datetime('now')), awarded_by INTEGER REFERENCES users(id));
